with scored as (select *, sum(revenue) over (partition by year(sale_date), store_id order by sale_date, id rows between unbounded preceding and current row) as running_revenue, corr(revenue, units) over (partition by store_id, product_id) as corr_revenue_units, row_number() over (partition by product_id order by revenue desc, id) as seq_no from store_sales), enriched as (select id, sale_date, units, revenue, corr_revenue_units, avg(revenue) over (partition by product_id order by corr_revenue_units, id rows between 2 preceding and current row) as revenue_avg_2, sum(seq_no) over (partition by store_id) as store_id_sum_seq_no, rank() over (order by seq_no desc nulls first) as seq_no_rank from scored), filtered as (select id, units, revenue, corr_revenue_units, revenue_avg_2, store_id_sum_seq_no, last_day(sale_date) as sale_date_month_end from enriched where sale_date > date '2023-04-30'), enriched_store_sales as (select id, revenue_avg_2, sale_date_month_end, first_value(store_id_sum_seq_no, true) over (order by units, id rows between unbounded preceding and current row) as first_known_store_id_sum_seq_no, percent_rank() over (partition by month(sale_date_month_end) order by corr_revenue_units) as corr_revenue_units_percent_rank, avg(store_id_sum_seq_no) over (order by sale_date_month_end, id rows between 6 preceding and current row) as store_id_sum_seq_no_avg_6, last_value(store_id_sum_seq_no) ignore nulls over (order by revenue_avg_2, id rows between unbounded preceding and current row) as last_known_store_id_sum_seq_no from filtered) select first_known_store_id_sum_seq_no, sum(last_known_store_id_sum_seq_no) as total_last_known_store_id_sum_seq_no, count(distinct id) as distinct_ids, count(distinct id) as distinct_ids_2, approx_percentile(last_known_store_id_sum_seq_no, array(0.25, 0.5, 0.75)) as last_known_store_id_sum_seq_no_quartiles, round(avg(first_known_store_id_sum_seq_no), 2) as avg_first_known_store_id_sum_seq_no from enriched_store_sales group by first_known_store_id_sum_seq_no order by distinct_ids nulls first
